#!/usr/bin/env node
/**
 * Validates the authored institutional-surface registry and the repository
 * projections that become required when a reservation is activated.
 *
 * A reserved slug owns identity across every projection. An active slug must
 * additionally have one localized, evidenced standalone page while remaining
 * outside archive/arc data and producing no God Script.
 *
 * LATTICE:BEGIN — generated by lib/build-lattice-headers.js from docs/lattice-map.json. Do not hand-edit; edit the JSON and regenerate.
 *   role      : fail-closed institutional-surface registry, identity-reservation, localization, and evidence validator
 *   reads     : config/institutional-surfaces.json
 *               pages∕*.html (existence, data-i18n bindings, and active projection markers, per registered slug)
 *               data/nodes.json (every registered institutional slug must remain outside archive indexing)
 *               data/arcs-v2.json (every registered institutional slug must remain outside narrative arcs)
 *               data/index.json (registered slugs must remain outside generated content maps)
 *               data/strings/compiled/scopes/production∕*.json (required active-locale bindings)
 *               docs/screenshots∕*.png (required active locale/theme/viewport evidence cells)
 *               dist∕*.js (no God Script may be generated for a registered institutional identity)
 *   writes    : stdout only — read-only; exits nonzero when registry or projections drift
 *   loaded-by : manual run: node lib/check-institutional-surfaces.js
 *               package.json (pr-ready and institutional-surfaces:check scripts)
 *               lib/audit-pages.js (registeredSurfaceSlugs feeds the shared discovery exclusion)
 *               tests/54-institutional-surfaces.test.js
 *   tested-by : tests/54-institutional-surfaces.test.js
 *
 *   CHANGE MAP — if you touch X here, also check:
 *     active page marker, runtime, or archive-boundary rules change:
 *       - config/institutional-surfaces.json entry schema
 *       - tests/54-institutional-surfaces.test.js active valid/invalid fixtures
 *       - docs/architecture/18-institutional-pages.md active-page invariants
 *     a new consumer needs institutional slugs:
 *       - import registeredSurfaceSlugs() or read the registry through this validated contract; do not add a second slug list
 * LATTICE:END
 */

'use strict';

const fs = require('fs');
const path = require('path');

const SCHEMA_VERSION = 'institutional-surfaces.registry/v1';
const STATES = new Set(['reserved', 'active']);
const ENTRY_KEYS = new Set([
  'state', 'kind', 'purpose', 'archive', 'runtime', 'strings', 'theme', 'evidence', 'origin',
]);
const NESTED_KEYS = {
  archive: new Set(['indexed', 'arcMembership']),
  runtime: new Set(['mode', 'godScript', 'shell']),
  strings: new Set(['scope', 'requiredLocales', 'plannedLocales']),
  theme: new Set(['family', 'variants']),
  evidence: new Set(['viewports', 'themes']),
  origin: new Set(['sourcePr']),
};

function isObject(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function addIssue(issues, check, message, slug = null) {
  issues.push({ check, slug, message });
}

function checkExactKeys(value, allowed, label, issues, slug) {
  if (!isObject(value)) {
    addIssue(issues, 'shape', `${label} must be an object`, slug);
    return false;
  }
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) addIssue(issues, 'unknown-field', `${label}.${key} is not part of the v1 contract`, slug);
  }
  for (const key of allowed) {
    if (!Object.hasOwn(value, key)) addIssue(issues, 'missing-field', `${label}.${key} is required`, slug);
  }
  return true;
}

function checkStringList(value, label, issues, slug, allowEmpty = false) {
  if (!Array.isArray(value) || (!allowEmpty && value.length === 0) || value.some(item => typeof item !== 'string' || !item)) {
    addIssue(issues, 'string-list', `${label} must be ${allowEmpty ? 'a' : 'a non-empty'} string array`, slug);
    return [];
  }
  if (new Set(value).size !== value.length) addIssue(issues, 'duplicate-value', `${label} contains duplicates`, slug);
  return value;
}

function readJson(filePath, fallback) {
  if (!fs.existsSync(filePath)) return fallback;
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function registeredSurfaceSlugs(registry) {
  if (!isObject(registry) || registry.schemaVersion !== SCHEMA_VERSION || !isObject(registry.surfaces)) {
    throw new Error(`institutional surface registry must use ${SCHEMA_VERSION} and contain a surfaces object`);
  }
  return Object.keys(registry.surfaces).sort();
}

function collectArcSlugs(arcsData) {
  const slugs = new Set();
  for (const arc of Object.values(arcsData || {})) {
    for (const section of (arc && arc.sections) || []) {
      for (const slug of section.slugs || []) slugs.add(slug);
    }
  }
  return slugs;
}

function escapeRegex(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function projectionContainsSlug(value, slug) {
  if (Array.isArray(value)) return value.some(item => projectionContainsSlug(item, slug));
  if (!isObject(value)) return false;
  if (value.slug === slug) return true;
  return Object.values(value).some(item => projectionContainsSlug(item, slug));
}

function identityProjectionIssues(slug, root) {
  const issues = [];
  const distPath = path.join(root, 'dist', `vextreme-${slug}.js`);
  if (fs.existsSync(distPath)) {
    addIssue(issues, 'god-script-output', `registered institutional identity produced dist/vextreme-${slug}.js`, slug);
  }

  const nodes = readJson(path.join(root, 'data', 'nodes.json'), []);
  if (nodes.some(node => node && node.slug === slug)) {
    addIssue(issues, 'archive-index', 'registered institutional identity must not appear in data/nodes.json', slug);
  }
  const arcs = readJson(path.join(root, 'data', 'arcs-v2.json'), {});
  if (collectArcSlugs(arcs).has(slug)) {
    addIssue(issues, 'arc-membership', 'registered institutional identity must not appear in data/arcs-v2.json', slug);
  }
  const index = readJson(path.join(root, 'data', 'index.json'), {});
  if (Object.hasOwn(index.slugMap || {}, slug) ||
      projectionContainsSlug(index.arcMap || {}, slug) ||
      projectionContainsSlug(index.departmentMap || {}, slug)) {
    addIssue(issues, 'generated-index', 'registered institutional identity leaked into data/index.json', slug);
  }
  return issues;
}

function pageI18nKeys(html) {
  const keys = new Set();
  const pattern = /\bdata-i18n=["']([^"']+)["']/g;
  let match;
  while ((match = pattern.exec(html))) keys.add(match[1]);
  return [...keys].sort();
}

function activeLocalizationIssues(slug, entry, html, root) {
  const issues = [];
  const keys = pageI18nKeys(html);
  if (keys.length === 0) {
    addIssue(issues, 'i18n-bindings', 'active page must contain at least one data-i18n binding', slug);
    return issues;
  }

  for (const locale of Array.isArray(entry.strings.requiredLocales) ? entry.strings.requiredLocales : []) {
    const relPath = path.join('data', 'strings', 'compiled', 'scopes', 'production', `${entry.strings.scope}.${locale}.json`);
    const bundlePath = path.join(root, relPath);
    if (!fs.existsSync(bundlePath)) {
      addIssue(issues, 'required-locale-bundle', `${relPath} is required before activation`, slug);
      continue;
    }
    let bundle;
    try {
      bundle = JSON.parse(fs.readFileSync(bundlePath, 'utf8'));
    } catch (error) {
      addIssue(issues, 'required-locale-bundle', `${relPath} is not valid JSON`, slug);
      continue;
    }
    for (const key of keys) {
      if (!isObject(bundle[key]) || typeof bundle[key].text !== 'string' || bundle[key].text.trim() === '') {
        addIssue(issues, 'required-locale-key', `${relPath} does not provide non-empty text for ${key}`, slug);
      }
    }
  }
  return issues;
}

function hasPngSignature(filePath) {
  if (!fs.existsSync(filePath) || fs.statSync(filePath).size < 8) return false;
  const signature = Buffer.alloc(8);
  const fd = fs.openSync(filePath, 'r');
  try {
    fs.readSync(fd, signature, 0, 8, 0);
  } finally {
    fs.closeSync(fd);
  }
  return signature.equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
}

function activeEvidenceIssues(slug, entry, root) {
  const issues = [];
  const locales = Array.isArray(entry.strings.requiredLocales) ? entry.strings.requiredLocales : [];
  const themes = Array.isArray(entry.evidence.themes) ? entry.evidence.themes : [];
  const viewports = Array.isArray(entry.evidence.viewports) ? entry.evidence.viewports : [];
  for (const locale of locales) {
    for (const theme of themes) {
      for (const viewport of viewports) {
        const relPath = path.join('docs', 'screenshots', `${slug}-${locale}-${theme}-${viewport}.png`);
        if (!hasPngSignature(path.join(root, relPath))) {
          addIssue(issues, 'evidence-matrix', `${relPath} must exist as a PNG before activation`, slug);
        }
      }
    }
  }
  return issues;
}

function activeSurfaceIssues(slug, entry, root) {
  const issues = [];
  const pagePath = path.join(root, 'pages', `${slug}.html`);
  if (!fs.existsSync(pagePath)) {
    addIssue(issues, 'active-page-missing', `active surface has no pages/${slug}.html`, slug);
    return issues;
  }

  const html = fs.readFileSync(pagePath, 'utf8');
  if (!/<html\b[^>]*\bdata-vex-surface=["']institutional["']/i.test(html)) {
    addIssue(issues, 'surface-marker', 'active page must project data-vex-surface="institutional" on <html>', slug);
  }
  const scopePattern = new RegExp(`\\bdata-vex-string-scope=["']${escapeRegex(entry.strings.scope)}["']`, 'i');
  if (!scopePattern.test(html)) {
    addIssue(issues, 'scope-marker', `active page must project data-vex-string-scope="${entry.strings.scope}"`, slug);
  }
  const familyPattern = new RegExp(`\\bdata-vex-theme-family=["']${escapeRegex(entry.theme.family)}["']`, 'i');
  if (!familyPattern.test(html)) {
    addIssue(issues, 'theme-family-marker', `active page must project data-vex-theme-family="${entry.theme.family}"`, slug);
  }
  const themeMatch = html.match(/<html\b[^>]*\bdata-theme=["']([^"']+)["']/i);
  const themeVariants = Array.isArray(entry.theme.variants) ? entry.theme.variants : [];
  if (!themeMatch || !themeVariants.includes(themeMatch[1])) {
    addIssue(issues, 'theme-variant-marker', 'active page data-theme must begin with one declared theme variant', slug);
  }
  if (/lib\/shell\.js|dist\/vextreme-[^"']+\.js/i.test(html)) {
    addIssue(issues, 'runtime-boundary', 'active institutional page must not load shell.js or a God Script', slug);
  }
  issues.push(...activeLocalizationIssues(slug, entry, html, root));
  issues.push(...activeEvidenceIssues(slug, entry, root));
  return issues;
}

function validateRegistry(registry, root = path.join(__dirname, '..')) {
  const issues = [];
  if (!isObject(registry)) return [{ check: 'registry-shape', slug: null, message: 'registry must be an object' }];
  if (registry.schemaVersion !== SCHEMA_VERSION) {
    addIssue(issues, 'schema-version', `schemaVersion must be ${SCHEMA_VERSION}`);
  }
  if (!isObject(registry.surfaces)) {
    addIssue(issues, 'surfaces-shape', 'surfaces must be an object keyed by slug');
    return issues;
  }

  for (const [slug, entry] of Object.entries(registry.surfaces)) {
    if (!/^(?:vex|vextreme)-[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) {
      addIssue(issues, 'slug', `${slug} must use the vex- or vextreme- institutional prefix`, slug);
    }
    if (!checkExactKeys(entry, ENTRY_KEYS, 'surface', issues, slug)) continue;
    let nestedShapesValid = true;
    for (const [section, allowed] of Object.entries(NESTED_KEYS)) {
      nestedShapesValid = checkExactKeys(entry[section], allowed, section, issues, slug) && nestedShapesValid;
    }
    if (!STATES.has(entry.state)) addIssue(issues, 'state', `state must be reserved or active`, slug);
    if (entry.kind !== 'institutional') addIssue(issues, 'kind', 'kind must be institutional', slug);
    if (typeof entry.purpose !== 'string' || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(entry.purpose)) {
      addIssue(issues, 'purpose', 'purpose must be a non-empty kebab-case semantic id', slug);
    }
    if (entry.archive?.indexed !== false || entry.archive?.arcMembership !== false) {
      addIssue(issues, 'archive-boundary', 'institutional surfaces must opt out of archive indexing and arcs', slug);
    }
    if (entry.runtime?.mode !== 'standalone' || entry.runtime?.godScript !== false || entry.runtime?.shell !== false) {
      addIssue(issues, 'runtime-boundary', 'institutional surfaces must use standalone runtime with shell and God Script disabled', slug);
    }
    if (typeof entry.strings?.scope !== 'string' || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(entry.strings.scope)) {
      addIssue(issues, 'string-scope', 'strings.scope must be a kebab-case scope id', slug);
    }
    const requiredLocales = checkStringList(entry.strings?.requiredLocales, 'strings.requiredLocales', issues, slug);
    const plannedLocales = checkStringList(entry.strings?.plannedLocales, 'strings.plannedLocales', issues, slug, true);
    if (!requiredLocales.includes('en')) addIssue(issues, 'required-english', 'requiredLocales must include en', slug);
    if (plannedLocales.some(locale => requiredLocales.includes(locale))) {
      addIssue(issues, 'locale-overlap', 'requiredLocales and plannedLocales must not overlap', slug);
    }
    const variants = checkStringList(entry.theme?.variants, 'theme.variants', issues, slug);
    if (typeof entry.theme?.family !== 'string' || !entry.theme.family) {
      addIssue(issues, 'theme-family', 'theme.family must be a non-empty string', slug);
    }
    const evidenceThemes = checkStringList(entry.evidence?.themes, 'evidence.themes', issues, slug);
    if (evidenceThemes.some(theme => !variants.includes(theme))) {
      addIssue(issues, 'evidence-theme', 'every evidence theme must exist in theme.variants', slug);
    }
    const viewports = entry.evidence?.viewports;
    if (!Array.isArray(viewports) || viewports.length === 0 || viewports.some(width => !Number.isInteger(width) || width <= 0)) {
      addIssue(issues, 'viewports', 'evidence.viewports must be a non-empty positive-integer array', slug);
    } else {
      if (new Set(viewports).size !== viewports.length) addIssue(issues, 'duplicate-value', 'evidence.viewports contains duplicates', slug);
      if (viewports.some((width, index) => index > 0 && width <= viewports[index - 1])) {
        addIssue(issues, 'viewport-order', 'evidence.viewports must be strictly ascending', slug);
      }
    }
    if (!Number.isInteger(entry.origin?.sourcePr) || entry.origin.sourcePr <= 0) {
      addIssue(issues, 'origin', 'origin.sourcePr must be a positive pull-request number', slug);
    }

    const pageExists = fs.existsSync(path.join(root, 'pages', `${slug}.html`));
    issues.push(...identityProjectionIssues(slug, root));
    if (entry.state === 'reserved' && pageExists) {
      addIssue(issues, 'reservation-stale', `pages/${slug}.html exists; promote the registry entry to active in the same PR`, slug);
    }
    if (entry.state === 'active' && nestedShapesValid) issues.push(...activeSurfaceIssues(slug, entry, root));
  }
  return issues;
}

function surfacesByState(registry, state) {
  return Object.entries(registry.surfaces || {})
    .filter(([, entry]) => entry.state === state)
    .map(([slug, entry]) => ({ slug, ...entry }))
    .sort((a, b) => a.slug.localeCompare(b.slug));
}

function run(root = path.join(__dirname, '..')) {
  const registryPath = path.join(root, 'config', 'institutional-surfaces.json');
  const registry = readJson(registryPath, null);
  return { registry, issues: validateRegistry(registry, root) };
}

if (require.main === module) {
  const report = run();
  if (process.argv.includes('--json')) {
    console.log(JSON.stringify({ clean: report.issues.length === 0, issues: report.issues }, null, 2));
  } else {
    console.log(`[check-institutional-surfaces] ${report.issues.length === 0 ? 'Registry and projections agree.' : `${report.issues.length} issue(s):`}`);
    for (const issue of report.issues) {
      console.log(`  [${issue.check}]${issue.slug ? ` ${issue.slug}:` : ''} ${issue.message}`);
    }
  }
  if (report.issues.length > 0) process.exitCode = 1;
}

module.exports = {
  SCHEMA_VERSION,
  collectArcSlugs,
  registeredSurfaceSlugs,
  identityProjectionIssues,
  activeSurfaceIssues,
  validateRegistry,
  surfacesByState,
  run,
};

// [VXG RealForever]
